!! (llm-notes)
!! Since template for converting string and character array from C++ to FORTRAN was not
!! specified, CodeLlama started to hallucinate. This module had to be manually written
!! based on the rules that were deterimend using conversations with ChatGPT. Fine tuning
!! may alleivate this issue. In conclusion, an accurate template is necessary for LLMs
!! to perform code translation. This requires domain knowledge as detailed knowledge 
!! of the codebase.

module plabel_mod
  use mxpart_mod
  use, intrinsic :: iso_c_binding
  implicit none

  private
    interface
      function get_plabel() bind(C, name="plabel_mod_plabel")
        import :: c_ptr, c_char
        type(c_ptr) :: get_plabel
      end function get_plabel     
    end interface

  public :: plabel, plabel_mod_init, plabel_mod_finalize

  character(kind=c_char, len=2), pointer, dimension(:) :: plabel => null()

contains

  subroutine plabel_mod_init()
    implicit none
    integer :: i,j
    character(c_char), pointer, dimension(:,:) :: tmp_ptr => null()

    allocate(plabel(mxpart))
    call c_f_pointer(get_plabel(), tmp_ptr, [3,mxpart])   
    do i=1,mxpart
       do j=1,2
        plabel(i)(j:j) = tmp_ptr(j,i)
       end do
    end do
    tmp_ptr => null()
  end subroutine plabel_mod_init

  subroutine plabel_mod_finalize()
    implicit none
    nullify(plabel)
  end subroutine plabel_mod_finalize

end module plabel_mod

